ALTER TABLE "orders" DROP CONSTRAINT "orders_paid_state_check";--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_paid_state_check" CHECK (("orders"."status" = 'pending' and "orders"."paid_at" is null and "orders"."razorpay_payment_id" is null and "orders"."provider_payment_status" is null and "orders"."fulfillment_status" = 'not_ready') or ("orders"."status" = 'paid' and "orders"."paid_at" is not null and "orders"."razorpay_order_id" is not null and "orders"."razorpay_payment_id" is not null and "orders"."provider_payment_status" = 'captured' and "orders"."fulfillment_status" in ('unfulfilled', 'fulfilled')));